# -*- coding: utf-8 -*-
# أمثلة رقمية وإفصاحات وأخطاء للمعايير التي كانت أقل تغطية (تُدمج بعد المحتوى الأساسي)
def E(ex,dis,err): return [("مثال تطبيقي رقمي",ex),("الإفصاح المطلوب عادةً",["• "+x for x in dis]),("أخطاء شائعة وكيف تتجنبها",["• "+x for x in err])]
DEEPA={
"IAS 10":E(["السنة المالية تنتهي 31 ديسمبر وتُعتمد القوائم في 1 مارس. في 20 يناير أفلس عميل كان مدينًا بـ 50,000 ريال منذ ديسمبر: الحدث يؤكد ظروفًا كانت قائمة في تاريخ التقرير، فهو حدث معدِّل.","قيد: مدين: مصروف خسائر ائتمانية 50,000 / دائن: مخصص خسائر ائتمانية 50,000.","وفي فبراير احترق مستودع بقيمة 400,000 ريال بعد التاريخ: حدث غير معدِّل، فلا يُعدَّل أي رقم ويُفصح عنه إن كان جوهريًا."],["طبيعة الحدث غير المعدِّل وتقدير أثره المالي أو بيان تعذّر التقدير.","تاريخ اعتماد إصدار القوائم ومن اعتمدها.","التوزيعات المعلنة بعد تاريخ التقرير (لا تُسجَّل التزامًا)."],["تسجيل توزيعات أعلنت بعد نهاية السنة كالتزام.","اعتبار كل حدث لاحق معدِّلًا؛ المعيار فارق: هل الظرف كان قائمًا في تاريخ التقرير؟","نسيان الإفصاح عن حدث جوهري غير معدِّل."]),
"IAS 20":E(["حصلت منشأة على منحة 60,000 ريال لشراء آلة تكلفتها 300,000 وعمرها 10 سنوات. بطريقة الدخل المؤجل: عند الاستلام مدين: بنك 60,000 / دائن: منحة حكومية مؤجلة 60,000.","سنويًا: مدين: منحة حكومية مؤجلة 6,000 / دائن: إيراد منحة 6,000 (60,000 ÷ 10).","بالطريقة البديلة (خصم المنحة من الأصل) تُسجَّل الآلة 240,000 ويكون الإهلاك 24,000 سنويًا؛ الأثر على الربح واحد."],["السياسة المحاسبية للمنح وطريقة العرض.","طبيعة المنح ومداها وأي شروط لم تُستوفَ بعد.","أشكال المساعدة الحكومية الأخرى التي استفادت منها المنشأة."],["الاعتراف بالمنحة قبل التأكد المعقول من استيفاء شروطها.","إدراج كامل المنحة إيرادًا عند الاستلام بدل توزيعها.","عدم رد المنحة عند الإخلال بالشروط."]),
"IAS 23":E(["اقترضت منشأة 2,000,000 ريال بفائدة 6% لبناء مبنى مدة سنة. الفائدة 120,000، وحققت 5,000 من استثمار مؤقت للقرض قبل الصرف، فالمبلغ القابل للرسملة 115,000.","قيد الفائدة: مدين: مصروف فوائد 120,000 / دائن: بنك 120,000.","قيد الرسملة: مدين: أعمال رأسمالية تحت التنفيذ 115,000 / دائن: مصروف فوائد 115,000."],["مبلغ تكاليف الاقتراض المرسملة في الفترة.","معدل الرسملة المستخدم عند الاقتراض العام."],["رسملة تكاليف على أصل غير مؤهل (يحتاج وقتًا طويلًا للإعداد).","الاستمرار في الرسملة بعد اكتمال الأصل أو توقف النشاط الإنشائي مدة طويلة.","إهمال خصم عوائد الاستثمار المؤقت في القرض المخصص."]),
"IAS 24":E(["تستأجر منشأة مبنى من شركة يملكها زوج المدير العام بإيجار سنوي 120,000 ريال، والمتبقي غير المسدد 30,000. المعاملة مع طرف ذي علاقة وتستلزم الإفصاح ولو كانت بسعر السوق.","لا قيد خاص بالمعيار، فالقيد المعتاد: مدين: مصروف إيجار 120,000 / دائن: ذمم دائنة — طرف ذو علاقة 30,000 وبنك 90,000؛ أما الإفصاح فيشمل العلاقة والمبلغ والرصيد."],["طبيعة العلاقة مع الأطراف ذات العلاقة وحجم المعاملات والأرصدة القائمة.","تعويضات كبار موظفي الإدارة بالإجمال.","الشروط والضمانات والمخصصات المسجلة على الأرصدة."],["إغفال أقارب الدرجة الأولى والشركات التي يسيطر عليها كبار المديرين.","الإفصاح عن المعاملات دون الأرصدة.","القول بأن المعاملة «بسعر السوق» دون دليل يدعمه."]),
"IAS 26":E(["خطة تقاعد أصولها بالقيمة العادلة 5,000,000 ريال والقيمة الحالية الاكتوارية للمنافع الموعودة 4,600,000. فائض الخطة 400,000 يُعرض في قائمة صافي الأصول المتاحة للمنافع أو في الإيضاحات بحسب الطريقة المختارة."],["القيمة الحالية الاكتوارية للمنافع الموعودة وطريقة حسابها.","الافتراضات الاكتوارية الرئيسية وتاريخ آخر تقييم."],["مزج أصول الخطة بأصول صاحب العمل.","استخدام افتراضات اكتوارية غير محدّثة."]),
"IAS 27":E(["استثمرت منشأة 1,000,000 ريال في شركة تابعة وسجّلتها في قوائمها المنفصلة بالتكلفة. حصلت على توزيعات 80,000 ريال.","قيد: مدين: بنك 80,000 / دائن: إيراد توزيعات أرباح 80,000.","إن نزل المبلغ القابل للاسترداد عن التكلفة اختُبر الانخفاض وفق IAS 36."],["الأساس المختار لقياس الاستثمارات (تكلفة، IFRS 9، أو حقوق الملكية).","قائمة بالشركات التابعة والزميلة ونسب الملكية ومكان التأسيس."],["الخلط بين القوائم المنفصلة والموحدة.","إثبات التوزيعات قبل نشوء الحق في استلامها."]),
"IAS 28":E(["اشترت منشأة 30% من شركة زميلة بـ 600,000 ريال، وربح الزميلة 200,000 ووزعت 20,000 ريال.","قيد الحصة من الربح: مدين: استثمار في زميلة 60,000 / دائن: حصة من أرباح زميلة 60,000.","قيد التوزيعات (6,000): مدين: بنك 6,000 / دائن: استثمار في زميلة 6,000. القيمة الدفترية النهائية 600,000 + 60,000 − 6,000 = 654,000."],["اسم الزميلة ونسبة الملكية وطريقة المحاسبة.","ملخص المعلومات المالية للزميلة.","أي قيود على قدرة الزميلة على تحويل التوزيعات."],["إثبات التوزيعات إيرادًا وفق طريقة حقوق الملكية.","نسيان إلغاء الأرباح غير المحققة على المعاملات بين المنشأة وزميلتها بحدود حصتها.","استمرار تسجيل الخسائر بعد أن يصل الاستثمار إلى صفر دون التزام."]),
"IAS 29":E(["اشترت منشأة أرضًا بـ 10,000 حين كان الرقم القياسي 100، والمؤشر في تاريخ التقرير 150. القيمة المعاد عرضها = 10,000 × 150 ÷ 100 = 15,000. فرق إعادة العرض 5,000 يُسجَّل مقابله بحسب البند (حقوق ملكية أو ربح وخسارة) وفق متطلبات المعيار.","البنود النقدية لا تُعاد عرضها لأنها بوحدة القياس الجارية، لكن يُحتسب ربح أو خسارة صافي المركز النقدي."],["أن القوائم أعيد عرضها بوحدة القياس الجارية والمؤشر المستخدم ومعدله.","ربح أو خسارة صافي المركز النقدي."],["إعادة عرض البنود النقدية.","تطبيق المعيار على اقتصاد لا تنطبق عليه مؤشرات التضخم المرتفع (نحو 100% تراكميًا خلال 3 سنوات)."]),
"IAS 32":E(["أصدرت منشأة أسهمًا ممتازة واجبة الاسترداد إلزاميًا بـ 100,000 ريال: هي التزام مالي لا حقوق ملكية. قيد: مدين: بنك 100,000 / دائن: التزام مالي 100,000، وتُعامل توزيعاتها مصروف فوائد.","سندات قابلة للتحويل بـ 1,000,000 ريال، والقيمة الحالية للالتزام بمعدل السوق دون خيار التحويل 900,000: قيد: مدين: بنك 1,000,000 / دائن: التزام مالي 900,000 / دائن: احتياطي خيار التحويل (حقوق ملكية) 100,000."],["شروط الأدوات المركبة وكيفية تقسيمها.","المقاصة بين الأصول والالتزامات إن وُجد حق نافذ قانونيًا ونية التسوية بالصافي."],["تصنيف أسهم ممتازة واجبة الاسترداد كحقوق ملكية.","إهمال تقسيم السندات القابلة للتحويل إلى مكوني الالتزام وحقوق الملكية."]),
"IAS 33":E(["صافي الربح 600,000 ريال ومتوسط الأسهم المرجح 200,000، فالربحية الأساسية 3.00 ريال. لدى المنشأة 20,000 خيار سعر ممارسته 10 والسعر السوقي المتوسط 15.","الأسهم الإضافية المخففة = 20,000 × (1 − 10 ÷ 15) = 6,667، والربحية المخففة = 600,000 ÷ 206,667 = 2.90 ريال.","لا قيد محاسبي؛ هذا إفصاح يُحسب على الربح وعدد الأسهم."],["الربحية الأساسية والمخففة بالأرقام المعروضة في قائمة الدخل.","مطابقة البسط والمقام لكل منهما."],["إدراج أدوات مضادة للتخفيف (تزيد الربحية).","عدم ترجيح الأسهم بالزمن.","تجاهل توزيعات الأسهم الممتازة في البسط."]),
"IAS 34":E(["تتوقع منشأة معدل ضريبة فعليًا سنويًا 20%، وربحها في الربع الأول 100,000 ريال. ضريبة الربع = 100,000 × 20% = 20,000.","قيد: مدين: مصروف ضريبة 20,000 / دائن: ضريبة مستحقة 20,000.","تكاليف موسمية تُحمَّل في وقت حدوثها ولا تُؤجَّل ولا تُستحق مقدمًا."],["بيان بأن القوائم الأولية تتبع السياسات نفسها للقوائم السنوية.","الأحداث الجوهرية منذ نهاية آخر فترة سنوية.","موسمية الأعمال أو دوريتها."],["تأجيل تكاليف لتسوية الأرباح بين الأرباع.","تطبيق معدل ضريبة الربع بدل المعدل السنوي المتوقع."]),
"IAS 38":E(["أنفقت منشأة 500,000 ريال على البحث (تُحمَّل مصروفًا) ثم 300,000 على تطوير برنامج بعد استيفاء الشروط (جدوى تقنية ونية الإكمال وقدرة على القياس). عمره 5 سنوات.","قيد الرسملة: مدين: أصل غير ملموس — تطوير 300,000 / دائن: بنك 300,000.","الإطفاء السنوي: 300,000 ÷ 5 = 60,000: مدين: مصروف إطفاء 60,000 / دائن: مجمع الإطفاء 60,000."],["الأعمار الإنتاجية وطرق الإطفاء.","إجمالي نفقات البحث والتطوير المعترف بها مصروفًا."],["رسملة تكاليف البحث.","الشهرة المتولدة داخليًا لا تُسجَّل أصلًا.","إطفاء أصل غير محدد العمر بدل اختباره سنويًا للانخفاض."]),
"IAS 40":E(["عقار استثماري بنموذج القيمة العادلة قيمته الدفترية 2,000,000 وقيمته العادلة بتقييم معتمد 2,150,000.","قيد: مدين: عقار استثماري 150,000 / دائن: ربح تغير القيمة العادلة 150,000. ولا يُهلك العقار بهذا النموذج."],["النموذج المختار (قيمة عادلة أو تكلفة) وأساليب التقييم.","إيرادات الإيجار والمصروفات التشغيلية المباشرة."],["خلط العقار المشغول ذاتيًا (IAS 16) بالاستثماري.","تغيير النموذج دون مبرر بالمعيار."]),
"IAS 41":E(["قطيع قيمته العادلة 500,000 ريال وتكاليف البيع 20,000، فالأصل البيولوجي 480,000. في العام التالي القيمة العادلة 540,000 والتكاليف 25,000 أي 515,000.","قيد: مدين: أصل بيولوجي 35,000 / دائن: ربح تغير القيمة العادلة 35,000 (الفرق 515,000 − 480,000)."],["وصف كل مجموعة من الأصول البيولوجية والافتراضات المستخدمة في القيمة العادلة.","مطابقة القيمة الدفترية بين بداية الفترة ونهايتها."],["إهلاك الأصول البيولوجية.","تجاهل تكاليف البيع عند القياس."]),
"IFRS 1":E(["منشأة انتقلت إلى IFRS وكانت قيمة معدات 900,000 ريال بالتكلفة الدفترية والقيمة العادلة وقت الانتقال 1,200,000. باختيار «التكلفة المفترضة» تُرفع الدفترية 300,000.","قيد: مدين: معدات 300,000 / دائن: أرباح محتجزة 300,000 (قبل أثر الضريبة المؤجلة)."],["مطابقة حقوق الملكية والدخل بين المعايير السابقة وIFRS.","الإعفاءات الاختيارية المستخدمة."],["تطبيق المعايير بأثر رجعي دون الاستفادة من الإعفاءات المسموح بها.","نسيان مطابقة الأرقام المقارنة."]),
"IFRS 2":E(["منحت منشأة 100 موظف 100 خيار لكل منهم، والقيمة العادلة 12 ريالًا، فترة الاستحقاق 3 سنوات ويُتوقع خروج 10%. إجمالي المصروف = 100 × 100 × 90% × 12 = 108,000 أي 36,000 سنويًا.","قيد سنوي: مدين: مصروف دفع بالأسهم 36,000 / دائن: احتياطي الدفع بالأسهم 36,000."],["وصف الترتيب وعدد الخيارات وأسعار الممارسة وطريقة التقييم.","إجمالي المصروف المعترف به في الفترة."],["إعادة قياس القيمة العادلة للخيارات المسوّاة بالأسهم بعد تاريخ المنح.","إهمال تعديل عدد الأدوات المتوقع استحقاقها."]),
"IFRS 5":E(["أصل قيمته الدفترية 400,000 ريال قررت الإدارة بيعه خلال سنة، والقيمة العادلة ناقصًا تكاليف البيع 360,000. يُصنَّف محتفظًا به للبيع ويُوقف إهلاكه.","قيد: مدين: خسارة انخفاض قيمة 40,000 / دائن: أصل (أو مجمع انخفاض) 40,000. ثم يُعرض الأصل منفصلًا بـ 360,000."],["وصف الأصل وظروف البيع وأي ربح أو خسارة.","القطاع المرتبط إن وُجد."],["الاستمرار في إهلاك الأصل بعد التصنيف.","التصنيف دون خطة بيع ملتزمة وجهد نشط للبيع."]),
"IFRS 6":E(["رسملت منشأة تكاليف استكشاف 800,000 ريال بحسب سياستها. قيد: مدين: أصول استكشاف وتقييم 800,000 / دائن: بنك 800,000.","وبعد ثبوت عدم الجدوى التجارية: مدين: مصروف انخفاض قيمة 800,000 / دائن: أصول استكشاف 800,000."],["السياسة المحاسبية لتكاليف الاستكشاف.","مبالغ الأصول والمصروفات والتدفقات المتعلقة بالاستكشاف."],["الاستمرار في رسملة التكاليف رغم مؤشرات الانخفاض."]),
"IFRS 7":E(["أرصدة ذمم إجمالية 1,000,000 ريال ومخصص خسائر ائتمانية 40,000، فالصافي 960,000. يلزم إيضاح يحلل الذمم بحسب الأعمار والمرحلة ويطابق حركة المخصص.","لا قيد خاص بالمعيار فهو إفصاحي."],["أنواع المخاطر (ائتمان وسيولة وسوق) وكيفية إدارتها.","تحليل استحقاقات الالتزامات المالية.","حساسية الأرباح لتغير أسعار الفائدة أو الصرف."],["الاكتفاء بوصف نوعي دون أرقام.","إهمال تحليل استحقاقات الالتزامات."]),
"IFRS 8":E(["إيرادات المنشأة 10,000,000 ريال. قطاع أ 1,200,000 (12%) فهو قطاع يجب الإفصاح عنه لتجاوزه 10%. قطاع ب 700,000 (7%) لا يستوفي الحد بمفرده إلا إن جُمّع أو أُفصح عنه اختياريًا.","يجب أن تغطي القطاعات المفصَح عنها 75% على الأقل من إيرادات المنشأة الخارجية."],["معلومات عن ربح أو خسارة كل قطاع وأصوله والتزاماته إن رُفعت لصانع القرار.","مطابقة مجموع القطاعات بالقوائم."],["تحديد القطاعات بحسب الهيكل القانوني بدل تقارير صانع القرار.","إغفال مطابقة المجاميع."]),
"IFRS 10":E(["تملك الأم 55% من تابعة حققت ربحًا 200,000 ريال. حصة الحصة غير المسيطرة 45% = 90,000، وحصة المجموعة 110,000.","تُستبعد بالكامل المعاملات بين شركات المجموعة: بيع من الأم إلى التابعة بـ 100,000 يُلغى ومعه أي ربح غير محقق في المخزون."],["الأحكام الجوهرية في تقييم السيطرة.","تفاصيل الحصص غير المسيطرة."],["اعتماد نسبة الملكية وحدها دون تقييم السيطرة الفعلية.","إغفال استبعاد الأرصدة والأرباح البينية."]),
"IFRS 11":E(["عملية مشتركة 50% تحقق إيرادًا 400,000 ريال: تُسجِّل المنشأة حصتها 200,000 من الإيراد وحصتها من الأصول والمصروفات. أما المشروع المشترك فيُحاسب عنه بحقوق الملكية كالزميلة (IAS 28)."],["طبيعة الترتيب والحصة فيه وطريقة المحاسبة.","الأحكام المستخدمة في التصنيف."],["تصنيف الترتيب بحسب الشكل القانوني فقط دون تحليل الحقوق والالتزامات."]),
"IFRS 12":E(["شركة مجموعة لديها حصة غير مسيطرة جوهرية 45% في تابعة: يُفصح عن اسم التابعة ونسبة الحصة وربح الحصة غير المسيطرة (مثلًا 90,000) وأرصدتها وأي قيود على تحويل الأصول."],["الأحكام الجوهرية لتحديد السيطرة والنفوذ.","ملخص مالي للتوابع ذات الحصص الجوهرية.","مخاطر الكيانات المهيكلة غير الموحدة."],["حذف الإفصاح عن القيود على تحويل الأصول داخل المجموعة."]),
"IFRS 13":E(["أسهم مدرجة 10,000 سهم بسعر سوق 25 ريالًا: القيمة العادلة 250,000 ريال (المستوى 1). تكلفة بيع متوقعة 5,000 لا تدخل في القيمة العادلة، بل تُطرح فقط عند القياس بالقيمة العادلة ناقصًا تكاليف البيع.","عقار تُقدَّر قيمته بمدخلات غير ملحوظة يقع في المستوى 3 ويحتاج إفصاحًا أوسع."],["مستوى التسلسل الهرمي لكل قياس بالقيمة العادلة وأساليب التقييم.","مطابقة حركة المستوى 3."],["اعتبار سعر الشراء هو القيمة العادلة دائمًا.","إدخال تكاليف المعاملة في القيمة العادلة."]),
"IFRS 14":E(["منشأة تطبق IFRS لأول مرة وتعمل في قطاع منظَّم أسعاره، وسجلت رصيدًا مدينًا تنظيميًا مؤجلًا 50,000 ريال. يُعرض بندًا منفصلًا في المركز المالي وبحركته منفصلة في الدخل."],["طبيعة التنظيم السعري وأرصدة الحسابات التنظيمية المؤجلة وحركتها."],["تطبيقه على منشأة لا تتبنى IFRS لأول مرة."]),
}

DEEPA.update({
"IAS 1":[("مثال تطبيقي رقمي",["منشأة لديها قرض 300,000 ريال، منه 100,000 يستحق خلال 12 شهرًا من تاريخ التقرير و200,000 بعدها. يُعرض الجزء 100,000 التزامًا متداولًا والباقي غير متداول.","قيد إعادة التصنيف (إن كان مسجلًا بالكامل غير متداول): مدين: قرض طويل الأجل 100,000 / دائن: الجزء المتداول من القرض 100,000."])],
"IAS 7":[("مثال تطبيقي رقمي",["صافي الربح 150,000 ريال، إهلاك 30,000، زيادة ذمم مدينة 20,000، زيادة مخزون 10,000، زيادة ذمم دائنة 15,000. التدفق التشغيلي بالطريقة غير المباشرة = 150,000 + 30,000 − 20,000 − 10,000 + 15,000 = 165,000.","شراء معدات 80,000 (استثماري) وسداد قرض 40,000 (تمويلي): صافي التغير في النقد = 165,000 − 80,000 − 40,000 = 45,000."])],
"IAS 8":[("مثال تطبيقي رقمي",["اكتُشف في 2026 أن إهلاك 2025 لم يُسجَّل بمقدار 12,000 ريال وهو جوهري. يُصحَّح بأثر رجعي بتعديل الأرقام المقارنة.","قيد (دون ضريبة): مدين: أرباح محتجزة افتتاحية 12,000 / دائن: مجمع الإهلاك 12,000 مع الإفصاح عن طبيعة الخطأ ومبلغ التعديل."])],
"IFRS 3":[("مثال تطبيقي رقمي",["دفعت منشأة 5,000,000 ريال للاستحواذ على 100% من شركة صافي أصولها المحددة بالقيمة العادلة 4,200,000. الشهرة = 5,000,000 − 4,200,000 = 800,000.","قيد: مدين: صافي الأصول المقتناة 4,200,000 + شهرة 800,000 / دائن: بنك 5,000,000. وتكاليف الاستحواذ 50,000 تُحمَّل مصروفًا."])],
})

DEEPA.update({
"IFRS 17":[("مثال تطبيقي رقمي مبسّط",["شركة تأمين أصدرت عقودًا تتوقع منها تدفقات داخلة (أقساط) 1,000 ريال وتدفقات خارجة (مطالبات ومصروفات) 800 ريال، والقيمة الحالية بعد الخصم 760 ريالًا، مع تعديل مخاطر غير مالية 40 ريالًا.","الربح المتوقع غير المكتسب هامش الخدمة التعاقدية = 1,000 − 760 − 40 = 200 ريال. لا يُعترف به فورًا بل يُوزَّع على فترة التغطية، فإذا كانت سنتين يُعترف بـ 100 ريال سنويًا.","لو كانت العقود مجحفة (تدفقات خارجة أكبر من الداخلة) لعُترف بالخسارة فورًا في الربح أو الخسارة."]),("الإفصاح المطلوب عادةً",["• مطابقة القيمة الدفترية لمجموعات العقود (التزام التغطية المتبقية والمطالبات المتكبدة).","• هامش الخدمة التعاقدية وكيف سيُعترف به عبر الزمن.","• الافتراضات المؤثرة ومعدلات الخصم وتعديل المخاطر."]),("أخطاء شائعة وكيف تتجنبها",["• تطبيقه على عقود ليست تأمينية (مثل ضمانات المنتجات العادية التي تتبع IFRS 15).","• الاعتراف بالربح المتوقع كله عند الإصدار.","• مزج العقود المربحة والمجحفة في مجموعة واحدة بلا تقسيم."])],
"IFRS S1":[("مثال تطبيقي",["شركة لوجستية تحدد أن أكبر مخاطر الاستدامة المؤثرة عليها ارتفاع تكلفة الوقود وتشريعات الانبعاثات. تفصح عن: الحوكمة (من يشرف على المخاطر)، الاستراتيجية (أثرها على الخطة 3 سنوات)، إدارة المخاطر (كيف تُحدَّد وتُرتَّب)، والمقاييس (استهلاك الوقود لكل 100 كم، نسبة الأسطول الكهربائي).","مثال مقياس: استهلاك 38 لترًا لكل 100 كم هذا العام مقابل 41 في العام السابق، بهدف 35 خلال سنتين."]),("خطوات التطبيق",["• حدّد المخاطر والفرص المؤثرة فعليًا على التدفقات والتمويل.","• اربط الإفصاح بالفترة المالية نفسها والقوائم المالية.","• وثّق مصدر كل رقم وطريقة حسابه حتى يقبل التدقيق.","• ابدأ بمخاطر محدودة قابلة للقياس ثم وسّع."]),("أخطاء شائعة وكيف تتجنبها",["• الإفصاح عن أهداف طموحة دون خطة أو ميزانية.","• أرقام غير موثقة أو من فترات مختلفة.","• عرض معلومات بلا ربط بأثرها المالي."])],
"IFRS S2":[("مثال تطبيقي رقمي",["شركة تستهلك 2,000,000 كيلوواط ساعة كهرباء، ومعامل الانبعاثات 0.5 كجم CO2 لكل كيلوواط ساعة: انبعاثات النطاق 2 = 1,000,000 كجم أي 1,000 طن.","وبحرق 100,000 لتر وقود مباشرة بمعامل 2.68 كجم/لتر: النطاق 1 = 268,000 كجم أي 268 طنًا. الإجمالي لهذين النطاقين 1,268 طن CO2."]),("خطوات التطبيق",["• قياس الانبعاثات (نطاق 1 و2 ثم 3) بمنهجية معروفة وعوامل انبعاث موثقة.","• تحليل سيناريوهات مناخية وأثرها على الإيرادات والتكاليف.","• ربط المخاطر الانتقالية والمادية بقرارات الاستثمار وخطط التمويل."]),("أخطاء شائعة وكيف تتجنبها",["• استخدام معاملات انبعاث قديمة أو غير معلنة المصدر.","• تجاهل النطاق 3 دون تبرير.","• إهمال ربط الإفصاحات المناخية بالقوائم المالية."])],
"IFRS for SMEs":[("مثال تطبيقي رقمي",["منشأة صغيرة أنفقت 300,000 ريال على تطوير برنامج داخلي. بحسب IFRS for SMEs تُحمَّل نفقات التطوير مصروفًا عند حدوثها (لا رسملة)، بخلاف IAS 38 الذي يسمح بالرسملة عند استيفاء الشروط.","قيد: مدين: مصروف تطوير 300,000 / دائن: بنك 300,000.","وبالمقابل الشهرة تُطفأ على عمرها المقدر (غالبًا 10 سنوات عند تعذر تقدير العمر): شهرة 500,000 ← إطفاء 50,000 سنويًا."]),("نقاط تبسيط مهمة",["• لا تصنيف مفصل لـ IFRS 9؛ نموذج أبسط للأدوات المالية الأساسية.","• أقل إفصاحات من المعايير الكاملة.","• الشهرة تُطفأ بدل الاختبار السنوي فقط."]),("أخطاء شائعة وكيف تتجنبها",["• الخلط بين مفاهيم المعايير الكاملة وSMEs في قوائم واحدة.","• استخدام المعيار دون التأكد أن اشتراطات الجهة المنظمة تسمح به."])],
})
